def move(index, command):
    offsets = {'вперёд': 1, 'назад': -1}
    if command not in offsets:
        raise ValueError('Используй команду вперёд или назад')
    return min(len(scenes)-1, max(0, index + offsets[command]))
position = move(position, 'вперёд')
